create extension if not exists "pgcrypto";
create type public.user_role as enum ('super_admin','admin','sales_manager','sales_executive','project_manager','support','content_manager','customer');
create type public.lead_status as enum ('new','contacted','qualified','site_survey','quotation_sent','negotiation','won','lost','follow_up');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role public.user_role not null default 'customer',created_at timestamptz default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,email text,city text,property_type text,monthly_bill text,solution text,preferred_contact_time text,message text,source text default 'website',status public.lead_status not null default 'new',assigned_to uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),profile_id uuid unique references public.profiles(id) on delete set null,lead_id uuid references public.leads(id) on delete set null,company_name text,address text,city text,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,brand text,model text,category text,capacity text,efficiency text,warranty text,description text,specifications jsonb default '{}',image_path text,datasheet_path text,availability text,featured boolean default false,created_at timestamptz default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),name text not null,location text,capacity text,system_type text,generation text,savings text,duration text,components jsonb default '[]',image_path text,testimonial text,is_published boolean default false,created_at timestamptz default now());
create table if not exists public.project_milestones(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id) on delete cascade,title text not null,status text default 'pending',completed_on date,sort_order int default 0);
create table if not exists public.quotations(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id) on delete cascade,status text default 'draft',system_size text,panels jsonb default '{}',inverter jsonb default '{}',structure jsonb default '{}',installation numeric,subsidy numeric,taxes numeric,total_project_cost numeric,customer_contribution numeric,payment_schedule jsonb default '[]',warranty text,terms text,created_at timestamptz default now());
create table if not exists public.quotation_items(id uuid primary key default gen_random_uuid(),quotation_id uuid references public.quotations(id) on delete cascade,label text not null,quantity numeric,unit_price numeric,total numeric);
create table if not exists public.service_requests(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id) on delete cascade,service_type text not null,description text,status text default 'open',assigned_to uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.subsidy_programs(id uuid primary key default gen_random_uuid(),program_name text not null,state text,description text,eligibility text,benefit text,effective_from date,effective_to date,official_source text,status text default 'draft',last_verified_at date,created_at timestamptz default now());
create table if not exists public.solar_calculation_settings(id uuid primary key default gen_random_uuid(),name text unique not null,value numeric not null,unit text,notes text,updated_at timestamptz default now());
create table if not exists public.faqs(id uuid primary key default gen_random_uuid(),question text not null,answer text not null,sort_order int default 0,is_published boolean default false);
create table if not exists public.blogs(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,body text,seo_title text,meta_description text,og_image_path text,status text default 'draft',published_at timestamptz,created_at timestamptz default now());
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),customer_id uuid references public.customers(id) on delete cascade,name text not null,storage_path text not null,created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),profile_id uuid references public.profiles(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text,entity_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create table if not exists public.site_settings(key text primary key,value jsonb default '{}',updated_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role <> 'customer'); $$;
alter table public.profiles enable row level security; alter table public.leads enable row level security; alter table public.customers enable row level security; alter table public.quotations enable row level security; alter table public.service_requests enable row level security; alter table public.documents enable row level security;
create policy "public can create leads" on public.leads for insert with check(true); create policy "staff manage leads" on public.leads for all using(public.is_staff()) with check(public.is_staff()); create policy "own profile" on public.profiles for select using(id=auth.uid() or public.is_staff()); create policy "own customer" on public.customers for select using(profile_id=auth.uid() or public.is_staff()); create policy "own quotes" on public.quotations for select using(exists(select 1 from public.customers c where c.id=customer_id and c.profile_id=auth.uid()) or public.is_staff()); create policy "own services" on public.service_requests for select using(exists(select 1 from public.customers c where c.id=customer_id and c.profile_id=auth.uid()) or public.is_staff()); create policy "own documents" on public.documents for select using(exists(select 1 from public.customers c where c.id=customer_id and c.profile_id=auth.uid()) or public.is_staff());
insert into storage.buckets(id,name,public) values('products','products',true),('projects','projects',true),('team','team',true),('certifications','certifications',false),('documents','documents',false),('quotations','quotations',false),('blog-images','blog-images',true) on conflict(id) do nothing;
create policy "public media" on storage.objects for select using(bucket_id in('products','projects','team','blog-images')); create policy "staff uploads" on storage.objects for insert with check(public.is_staff()); create policy "private owners" on storage.objects for select using(bucket_id in('documents','quotations') and (public.is_staff() or (storage.foldername(name))[1]=auth.uid()::text));